def absolute(paths: list[str]) -> list[Path]:
    return [Path(p) if Path(p).is_absolute() else ROOT / p for p in paths]


def main() -> None:
    parser = argparse.ArgumentParser(description="Run and record each Sepsis-associated MOF study operation.")
    parser.add_argument("action", choices=sorted(STEPS))
    parser.add_argument("arguments", nargs=argparse.REMAINDER, help="Pass script options after --")
    args = parser.parse_args(); script, inputs, outputs = STEPS[args.action]
    forwarded = args.arguments[1:] if args.arguments[:1] == ["--"] else args.arguments
    command = [sys.executable, str(ROOT / script), *forwarded]
    started = datetime.now(timezone.utc); run_id = started.strftime("%Y%m%dT%H%M%S%fZ")
    RUN_DIR.mkdir(parents=True, exist_ok=True); log_path = RUN_DIR / f"{run_id}_{args.action}.log"
    with log_path.open("w", encoding="utf-8") as log_handle:
        process = subprocess.Popen(command, text=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, bufsize=1)
        assert process.stdout is not None
        for line in process.stdout:
            print(line, end="", flush=True)
            log_handle.write(line)
            log_handle.flush()
        returncode = process.wait()
    finished = datetime.now(timezone.utc)
    record = make_record(args.action, command, "success" if returncode == 0 else "failed", started, finished, absolute(inputs), absolute(outputs), log_path)
    append_record(RUNS, record)
    if returncode:
        raise SystemExit(returncode)


if __name__ == "__main__":
    main()
